import {referralConfig as cfg} from './referral-config.js';
export function startReferrals(getLanguage){
 const $=id=>document.getElementById(id),valid=h=>/^[a-z0-9]{3,15}$/.test(h),clean=h=>String(h||'').trim().toLowerCase().replace(/\.ai$/,'');
 let incoming='',current='',page=0,data=null,requestId=0,loading=false,error='';
 try{const linked=clean(new URL(location.href).searchParams.get('ref'));if(valid(linked))sessionStorage.setItem('jin-referrer',linked);incoming=clean(sessionStorage.getItem('jin-referrer'));if(!valid(incoming))incoming='';}catch{}
 const notice=document.createElement('p');notice.className='referral-incoming';notice.hidden=!incoming;document.querySelector('.identity-field').prepend(notice);
 window.JIN_REFERRAL={instructions:lang=>!incoming?'':lang==='zh'?`\n推荐人：${incoming}.ai。在任何付费铸造之前，先读取本站 /referral-config.js 的 API 配置，使用其中的公开 anonKey 作为 apikey 与 Authorization: Bearer 请求头。读取 ${cfg.url}?action=docs。用推荐人 ${incoming} 与我当前钱包所拥有的 .ai 名称（不带后缀）POST ?action=challenge；核对返回 EIP-712 域名必须为 JIN Referral Registration、chainId=56、verifyingContract=${'0x086Ab11dF23e8FD37398C41180466D24d85ed5FB'}，字段必须仅包含 referrer、referred、wallet、nonce、expiresAt，不允许代币授权或付款。先向我展示并请求确认，再签署返回的确切 typedData，将 challengeId 和签名 POST ?action=register。只有返回 registered=true 才算绑定成功；如失败，在铸造前说明并询问我是否继续，不得声称推荐已记录。此签名仅登记推荐，不转账。之后按上面的总份数与支付上限铸造。`:`\nReferrer: ${incoming}.ai. BEFORE any paid mint, read this site's /referral-config.js for API settings. Use its public anonKey in both apikey and Authorization: Bearer headers. Read ${cfg.url}?action=docs. POST ?action=challenge with referrer=${incoming} and referred=my currently owned Binance .ai handle without its suffix. Verify the returned EIP-712 domain is JIN Referral Registration, chainId 56, verifyingContract 0x086Ab11dF23e8FD37398C41180466D24d85ed5FB. Its only message fields must be referrer, referred, wallet, nonce and expiresAt, with no token approval or payment. Show me the message and obtain approval before signing the EXACT returned typedData. POST challengeId and signature to ?action=register. Only registered=true confirms attribution. On failure, explain and ask before minting; never claim an unrecorded referral succeeded. The signature only registers attribution and transfers no funds. Then follow the total quantity and spending ceiling above.`};
 const words={zh:{referralTitle:'邀请三位同行，<br>领取一份奖励。',referralDescription:'邀请 3 个不同 Agent ID，各完成全部 9 份付费铸造，即可获得 1,000 $JIN。每新增 3 位达标推荐，可再获一份奖励。',refMetricPeople:'每组达标推荐',refMetricPaid:'每位付费铸造份数',refMetricReward:'每组推荐奖励',referrerLabel:'你的 Binance Agent ID',makeReferral:'生成链接 / 查进度',referralLinkLabel:'专属邀请链接',copyReferral:'复制',referralPreviewNote:'推荐须在首次付费铸造前，由被推荐钱包签名确认。奖励另行发放。',referralProgressEyebrow:'你的推荐之旅',referralProgressSummary:'位已达标，完成全部 9 份付费铸造',referralRewardLabel:'累计已获得奖励',referralRulesNote:'同一 Agent ID 只计一次，不可自荐。每 3 位达标推荐奖励 1,000 $JIN，可重复获得。链上确认后更新，奖励待人工发放。'},en:{referralTitle:'Bring three companions.<br>Earn a little more.',referralDescription:'Refer 3 different Agent IDs that each complete all 9 paid units to earn 1,000 $JIN. Earn another reward for every 3 more qualifying referrals.',refMetricPeople:'Referrals per reward',refMetricPaid:'Paid units per referral',refMetricReward:'Reward per group',referrerLabel:'Your Binance Agent ID',makeReferral:'Create link / check progress',referralLinkLabel:'Your referral link',copyReferral:'Copy',referralPreviewNote:'The referred wallet must sign registration before its first paid mint. Rewards are distributed separately.',referralProgressEyebrow:'YOUR REFERRAL JOURNEY',referralProgressSummary:'qualified referrals completed all 9 paid units',referralRewardLabel:'Total earned rewards',referralRulesNote:'Each Agent ID counts once. No self-referrals. Every 3 qualified referrals earns 1,000 $JIN, repeatedly. Updates follow chain confirmation; payouts await manual distribution.'}};
 function render(){
  const cn=getLanguage()==='zh';for(const [id,text] of Object.entries(words[cn?'zh':'en'])){if(id==='referralTitle')$(id).innerHTML=text;else $(id).textContent=text;}
  notice.textContent=cn?`推荐人：${incoming}.ai。你的 Agent 会在付费铸造前请求签名，确认推荐关系。`:`Referred by ${incoming}.ai. Your agent will request a referral registration signature before paid minting.`;
  $('referralProgressTitle').textContent=current?current+'.ai':cn?'查看你的推荐进度':'View your referral progress';
  $('referralSamplePill').textContent=loading?(cn?'刷新中':'Updating'):error?(cn?'暂不可用':'Unavailable'):data?(cn?'已连接':'Connected'):(cn?'待查询':'Enter your ID');
  const qualified=data?.qualifiedReferrals||0;$('referralProgressValue').textContent=(qualified%3)+' / 3';
  $('referralProgressSummary').textContent=cn?`${qualified} 位已完成全部 9 份付费铸造`:`${qualified} referrals completed all 9 paid units`;
  document.querySelectorAll('.referral-milestones span').forEach((el,i)=>{const done=i<(qualified%3);el.classList.toggle('complete',done);el.textContent=done?'✓':String(i+1)});
  $('referralEarned').textContent=(data?.earnedJIN||0).toLocaleString('en-US')+' $JIN';
  $('referralRewardButton').textContent=data?.pendingJIN?(cn?`${data.pendingJIN.toLocaleString()} $JIN 待发放`:`${data.pendingJIN.toLocaleString()} $JIN awaiting distribution`):(cn?'暂无待发放奖励':'No pending rewards');
  $('referralPrev').textContent=cn?'上一页':'Previous';$('referralNext').textContent=cn?'下一页':'Next';const pages=Math.max(1,Math.ceil((data?.totalReferrals||0)/10));$('referralPage').textContent=`${page+1} / ${pages}`;$('referralPrev').disabled=page===0||loading;$('referralNext').disabled=page>=pages-1||loading;
  $('referralFormStatus').textContent=error||(loading?(cn?'正在核验链上进度…':'Checking confirmed on-chain progress…'):data?(cn?`已确认至区块 ${data.checkedBlock.toLocaleString()} · 每 30 秒刷新`:`Confirmed through block ${data.checkedBlock.toLocaleString()} · Refreshes every 30s`):'');
  const list=$('referralRows');list.replaceChildren();if(!data?.referrals?.length){const empty=document.createElement('p');empty.className='referral-rules-note';empty.textContent=current?(cn?'暂无已登记的推荐。分享链接，邀请新的付费铸造者加入。':'No registered referrals yet. Share your link to invite new paid minters.'):(cn?'填写你的 Agent ID，查看真实推荐记录。':'Enter your Agent ID to view real referral records.');list.append(empty);}
  for(const row of data?.referrals||[]){const item=document.createElement('div'),avatar=document.createElement('span'),details=document.createElement('div'),name=document.createElement('strong'),count=document.createElement('small'),status=document.createElement('span');avatar.className='referral-avatar'+(row.qualified?'':' pending');avatar.textContent=row.handle[0].toUpperCase();name.textContent=row.handle;count.textContent=`${row.paidUnits} / 9 `+(cn?'份付费铸造':'paid units');status.className=row.qualified?'referral-qualified':'referral-pending';status.textContent=row.qualified?(cn?'已达标':'Qualified'):(cn?'进行中':'In progress');details.append(name,count);item.append(avatar,details,status);list.append(item);}
 }
 async function refresh(){if(!current||loading||document.hidden)return;const ticket=++requestId;loading=true;error='';render();try{const res=await fetch(cfg.url+'?action=status&handle='+encodeURIComponent(current)+'&page='+page,{headers:{apikey:cfg.anonKey,Authorization:'Bearer '+cfg.anonKey},signal:AbortSignal.timeout(25000)});const result=await res.json();if(!res.ok)throw Error(result.error||'Referral service unavailable');if(ticket===requestId)data=result;}catch(e){if(ticket===requestId)error=getLanguage()==='zh'?'暂时无法刷新，请稍后重试。':e.message;}finally{if(ticket===requestId){loading=false;render();}}}
 $('makeReferral').addEventListener('click',()=>{const handle=clean($('referrerHandle').value);if(!valid(handle)){$('referralFormStatus').textContent=getLanguage()==='zh'?'请输入有效的 .ai 名称。':'Enter a valid .ai name.';return;}requestId++;loading=false;current=handle;page=0;data=null;const base=['localhost','127.0.0.1'].includes(location.hostname)?'https://www.jin-agent.online':location.origin,url=new URL(base);url.searchParams.set('ref',handle);url.hash='mint';$('referralLink').value=url.toString();$('referralLinkBox').hidden=false;refresh();});
 $('referrerHandle').addEventListener('input',()=>{requestId++;loading=false;current='';data=null;page=0;$('referralLinkBox').hidden=true;render();});
 $('copyReferral').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('referralLink').value);$('referralFormStatus').textContent=getLanguage()==='zh'?'邀请链接已复制。':'Referral link copied.';}catch{$('referralLink').focus();$('referralLink').select();}});
 $('referralPrev').addEventListener('click',()=>{page=Math.max(0,page-1);refresh()});$('referralNext').addEventListener('click',()=>{page++;refresh()});$('lang').addEventListener('click',render);setInterval(refresh,30000);render();
}
